/* Malware scanning: public.file_scans, one row per file the Storelib file scanner (ClamAV) looked at: where it came from, the verdict, the threat's name, the size, the SHA-256, how long it took, and what Storelib did with the file (kept, removed, refused, pending). Never the file's contents. /admin/scanner reads it and only the server writes it: row level security on, no policy, nothing granted to the browser. Also makes sure digital_assets has the scan_status and scan_result columns the scan writes (they are there on any database that ran the upload migrations; this only adds them where they are missing) and indexes the files still waiting for a verdict. Changes no rows. Needs nothing else. Until it runs, scanning works the same and the admin page says the log starts after this part. */
CREATE TABLE IF NOT EXISTS public.file_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), source text NOT NULL, bucket text, path text, asset_id uuid, status text NOT NULL CHECK (status IN ('clean', 'infected', 'error', 'not_scanned')), threat text, reason text, sha256 text, bytes bigint, duration_ms integer, engine_version text, signatures integer, action text, attempts smallint);
CREATE INDEX IF NOT EXISTS file_scans_created_idx ON public.file_scans (created_at DESC);
CREATE INDEX IF NOT EXISTS file_scans_asset_idx ON public.file_scans (asset_id) WHERE asset_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS file_scans_flagged_idx ON public.file_scans (created_at DESC) WHERE status IN ('infected', 'error');
ALTER TABLE public.file_scans ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_scans FROM anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.digital_assets') IS NOT NULL THEN ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_status text DEFAULT 'pending_scan'; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_result jsonb; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'digital_assets' AND column_name = 'updated_at') THEN CREATE INDEX IF NOT EXISTS digital_assets_scan_waiting_idx ON public.digital_assets (updated_at) WHERE scan_status IN ('pending_scan', 'scanning'); END IF; END IF; END $do$;
notify pgrst, 'reload schema';
